import { AspectRatio, Text, VStack } from '@advui/core'
import { Image } from 'react-native'

export default function AspectRatioBasic() {
  return (
    <VStack gap="$2" width="100%" maxWidth="$96">
      <AspectRatio ratio={16 / 9} borderRadius="$lg" backgroundColor="$muted">
        <Image
          source={{
            uri: 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?w=900&q=70',
          }}
          style={{ width: '100%', height: '100%' }}
          accessibilityLabel="A desert road between red rock canyons"
        />
      </AspectRatio>
      <Text size="sm" tone="muted">
        The photo stays 16:9 at any width.
      </Text>
    </VStack>
  )
}

import { AspectRatio, Center, HStack, Text } from '@advui/core'

const ratios = [
  { label: '1:1', ratio: 1 },
  { label: '4:3', ratio: 4 / 3 },
  { label: '16:9', ratio: 16 / 9 },
]

export default function AspectRatioRatios() {
  return (
    <HStack gap="$3" flexWrap="wrap" alignItems="flex-start">
      {ratios.map((item) => (
        // Same width, so the height alone shows the ratio.
        <AspectRatio
          key={item.label}
          ratio={item.ratio}
          width="$32"
          borderRadius="$md"
          borderWidth={1}
          borderColor="$border"
          backgroundColor="$muted"
        >
          <Center flex={1}>
            <Text size="sm" weight="medium">
              {item.label}
            </Text>
          </Center>
        </AspectRatio>
      ))}
    </HStack>
  )
}
